    89	  hb_blob_t *get_glyph_blob (unsigned int  glyph_id,
    90	                             hb_blob_t    *sbix_blob,
    91	                             hb_tag_t      file_type,
    92	                             int          *x_offset,
    93	                             int          *y_offset,
    94	                             unsigned int  num_glyphs,
    95	                             unsigned int *strike_ppem) const
    96	  {
    97	    if (unlikely (!ppem)) return hb_blob_get_empty (); /* To get Null() object out of the way. */
    98	
    99	    unsigned int retry_count = 8;
   100	    unsigned int sbix_len = sbix_blob->length;
   101	    unsigned int strike_offset = (const char *) this - (const char *) sbix_blob->data;
   102	    assert (strike_offset < sbix_len);
   103	
   104	  retry:
   105	    if (unlikely (glyph_id >= num_glyphs ||
   106	                  imageOffsetsZ[glyph_id + 1] <= imageOffsetsZ[glyph_id] ||
   107	                  imageOffsetsZ[glyph_id + 1] - imageOffsetsZ[glyph_id] <= SBIXGlyph::min_size ||
   108	                  (unsigned int) imageOffsetsZ[glyph_id + 1] > sbix_len - strike_offset))
   109	      return hb_blob_get_empty ();
   110	
   111	    unsigned int glyph_offset = strike_offset + (unsigned int) imageOffsetsZ[glyph_id] + SBIXGlyph::min_size;
   112	    unsigned int glyph_length = imageOffsetsZ[glyph_id + 1] - imageOffsetsZ[glyph_id] - SBIXGlyph::min_size;
   113	
   114	    const SBIXGlyph *glyph = &(this+imageOffsetsZ[glyph_id]);
   115	
   116	    if (glyph->graphicType == HB_TAG ('d','u','p','e'))
   117	    {
   118	      if (glyph_length >= 2)
   119	      {
   120	        glyph_id = *((HBUINT16 *) &glyph->data);
   121	        if (retry_count--)
   122	          goto retry;
   123	      }
   124	      return hb_blob_get_empty ();
   125	    }
   126	
   127	    if (unlikely (file_type != glyph->graphicType))
   128	      return hb_blob_get_empty ();
   129	
   130	    if (strike_ppem) *strike_ppem = ppem;
   131	    if (x_offset) *x_offset = glyph->xOffset;
   132	    if (y_offset) *y_offset = glyph->yOffset;
   133	    return hb_blob_create_sub_blob (sbix_blob, glyph_offset, glyph_length);
   134	  }
