   216	    hb_blob_t *reference_png (hb_font_t      *font,
   217	                              hb_codepoint_t  glyph_id,
   218	                              int            *x_offset,
   219	                              int            *y_offset,
   220	                              unsigned int   *available_ppem) const
   221	    {
   222	      return choose_strike (font).get_glyph_blob (glyph_id, table.get_blob (),
