   347	  bool serialize_strike_offsets (hb_subset_context_t *c,
   348	                                 const void *dst_base,
   349	                                 unsigned int sbix_len) const
   350	  {
   351	    TRACE_SERIALIZE (this);
   352	
   353	    auto *out = c->serializer->start_embed<LOffsetLArrayOf<SBIXStrike>> ();
   354	    if (unlikely (!out)) return_trace (false);
   355	    if (unlikely (!c->serializer->extend_min(out))) return_trace (false);
   356	
   357	    hb_vector_t<LOffsetTo<SBIXStrike>*> new_strikes;
   358	    hb_vector_t<hb_serialize_context_t::objidx_t> objidxs;
   359	    for (int i = strikes.len - 1; i >= 0; --i)
   360	    {
   361	      auto* o = out->serialize_append (c->serializer);
   362	      if (unlikely (!o)) return_trace (false);
   363	      *o = 0;
   364	      auto snap = c->serializer->snapshot ();
   365	      c->serializer->push ();
   366	      bool ret = add_strike(c, dst_base, i, sbix_len);
   367	      if (!ret)
   368	      {
   369	        c->serializer->pop_discard ();
   370	        out->pop();
   371	        c->serializer->revert (snap);
   372	      }
   373	      else
   374	      {
   375	        objidxs.push (c->serializer->pop_pack ());
   376	        new_strikes.push (o);
   377	      }
   378	    }
   379	    for (unsigned int i = 0; i < new_strikes.length; ++i)
   380	      c->serializer->add_link (*new_strikes[i], objidxs[new_strikes.length - 1 - i], dst_base);
   381	
   382	    return_trace (true);
   383	  }
